Definition blk2 (BL : CA.blocks) : option (expr * expr) :=
  match BL with [(pe, ce); (sb, sc)] => if (expr_eqb sb SBx && expr_eqb sc SCAP)%bool then Some (pe, ce) else None | _ => None end.
Definition view_chk (more_lit : Z) (cells : list kentry) (BL : CA.blocks) : option (expr * expr * PB2.pvals) := ltac2:(Rpl.RP.run_i (rplG ()) 3 "S40!2+J+S+S!2+J0+^5!1+I1!1,^K1$more_lit;R+K$cells;R!1+^2+^3$BL;R'^4-IRN$x;R!1+I02!1'^6#12$p;R0-JRN$p;R!2+J+S+S2#11$pe;R+S$ce;R+S-IRN$x;R!1+I+^52!7'^7#5'Y#2#1'^8'^9'^:2$pv;R+^5-:RN$~R+:2!2'T!2'T!2'T!2'T!2'T!2'T!2'T!2'U!1'^;#1!1,X!1,0|37;!2'U!1'^<#1!1,X#7!2'U!1'^=#1'^>!2'U!1'^?#1'^@!2'U!1'^A#1'^B!2'U!1'^C#1'7!2'U!1'^D#1'^E!2'^F#6!3,^G!1'^H#1,Z!1,0|33;2!2,^I1!4,^J0+^5!4,^J+S+S#3#2#1333").
Definition ESC_NEED : list Z := ltac2:(Rpl.RP.run_i (rplG ()) 0 "S30!1,0,^M!1,0|10;!1,0|11;!3,^L+K,Z!3,^L+K,Z!3,^L+K,Z!3,^L+K0!3,^L+K1!3,^L+K2!3,^L+K,Z!3,^L+K,Z!3,^L+K,Z!3,^L+K0!3,^L+K1!3,^L+K2!1,^N+K").   (* [comment removed for export] *)
Definition need_of (sst : expr) : option Z := match sst with ELit z => if (Z.leb 0 z && Z.leb z 11)%bool then Some (nth (Z.to_nat z) ESC_NEED 0) else None | _ => None end.
(* [comment removed for export] *)
Definition cur_chk (cells : list kentry) (a0e se : expr) (need : Z) : bool :=
  (PB.prove cells (KRange (APC.esub a0e SEG) 0 16384) && PB.prove cells (KRange (APC.esub WEND a0e) 0 16384)
   && PB.prove cells (KRange (APC.esub BX (APC.eaddz (APC.eadd se (APC.esub WEND a0e)) need)) 0 67108864))%bool.
Definition progress_chk (cells : list kentry) (a0e : expr) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 2 "S00$cells;R!1+^2+^3$a0e;R+S!2'^O!2'^F#2!3,^G!2'^P#1'7!1,0,^M!1,0|>0000;!2'^F#2!3,^G!2'^P'^E#1,Z,Z").

Definition exit_pre_chk (i : nat) (c : CC.cutpoint) (ps : SR.post_spec) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 3 "S50!1,X,Z!2+J+S+S!4'^S'^4#5'^\!1,^N1!2+J1+^5}4$i;R+H$c;R+[$ps;R+^Q&cells;R!1'^R#1!1+^2+^3&a0e;R!4'^S+S}:!1'^T#20+S!2'T!2'T!2'T!2'T!4'^U'^V'^W#4#3!1'^X#3!1'^Y#4!2'^Z!1'^[#42-IRN$x;R!1+I3+:!3'_0!1,0,^M#222$p;R3-JRN$p;R!2+J1+^5+:#11$p0;R1$pv;R+^5-JRN$p0;R!2+J+S+S+:#21$pe;R+S$ce;R+S-IRN$x;R!1+I+K+:!1'_1!1'^H#32$need;R+K!2'T!2'T!2'_2#8!3,_3!2,_4'_5,Z40!4'_6#8#7!1'_7#4#1!2'_8#8#7,<,<").
Definition exit_setec_chk (i : nat) (c : CC.cutpoint) (ps : SR.post_spec) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 3 "S50!2+J+S+S!4'^S'^4#5'^\!1,^N0!2+J0+^5}4}8$i;R+H$c;R+[$ps;R+^Q&cells;R!1'^R#1!1+^2+^3&a0e;R!4'^S+S}:!1'^T#2!1,X,Z+S!2'T!2'T!2'T!2'T!4'^U'^V'^W#4#3!1'^X#3!1'^Y#4!2'^Z!1'^[#41-IRN$x;R!1+I2+:!3'_0,Z#212$p;R2-JRN$p;R!2+J0+^5+:#11$p0;R0$pv;R+^5-JRN$p0;R!2+J+S+S+:#21$pe;R+S$ce;R+S-IRN$x;R!1+I+S+:!4'_9#7'_5,Z32$e;R+S-SRN$e;R+S+:#18$code;R+K!2'T!2'T!2'T!2'_:!1,0,^M#1!2'_:#1!1,0|4f;!2'_2#9!3,_3!2,_4'_5!1,0|30;4!1,X'_;!4'_6#9#8!1'_7#5,Z$n;R+H,<$op;R+_<$a;R+S$b;R+S,<$op;R+_<$a;R+S$b;R+S,<$op;R+_=$a;R+S$b;R+S,<$op;R+_=$a;R+S$b;R+S,<$sx;R+:$lo;R+H$n;R+H$e0;R+S,<$sx;R+:$k;R+H$i0;R+K$n;R+H,<,<,<").
Definition ghost_of (c : CC.cutpoint) : nat := ltac2:(Rpl.RP.run_i (rplG ()) 1 "S00$c;R+[!2'_>!2'_>!1'^[#1'_?}5").
Definition s1_of (c : CC.cutpoint) : expr := nth 21 (CC.cp_regs c) (ELit 0).
Definition exit_esv_chk (i : nat) (c : CC.cutpoint) (ps : SR.post_spec) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 3 "S40!1'^[#5!1'_D#5!2'^P#21!1,0,^M$i;R+H$c;R+[$ps;R+^Q&cells;R!1'^R#1!1+^2+^3&a0e;R!4'^S+S}:!1'^T#2!1,X,Z+S&g;R!1,5!1'_A#4+S!2'T!2'T!2'T!2'T!2'T!2'T!4'^U'^V'^W#5#4!1'^X#4!1'_B#5!2'^Z0!4'^S'^4#6'^\!1,^N!2+J+S+S!2'_C01!2'_E!1'_A#50!2'^O!2'T!2'^F#3!3,^G#1,Z,Z!2'^F#3!3,^G233!2'T!2'^F#3!3,^G#13!1,0|4f;!2'^F#3!3,^G2,Z,Z").

(* [comment removed for export] *)
Definition esv_leaf_chk (i : nat) (c : CC.cutpoint) (ps : SR.post_spec) (cj : CC.cutpoint) : bool :=
  let cells := SR.ps_cells ps in let regs := CA.ps_reglist ps in
  let s1 := nth 21 regs (ELit 0) in let a1e := nth 11 regs (ELit 0) in let a2e := nth 12 regs (ELit 0) in
  (CH2.blocks_vars_lt (CC.cp_nx c) (nth i G.BLS []) && expr_eqb (nth 10 regs (ELit 0)) Pb && expr_eqb (nth 13 regs (ELit 0)) Vb && expr_eqb (nth 14 regs (ELit 0)) Eb && expr_eqb (s1_of cj) s1 &&
   match view_chk 1 cells (nth i G.BLS []) with
   | Some (pe, ce, pv) =>
       (PB.has cells (KWord (SA Eb 0) 4 (ELit 0)) && PB.has cells (KWord (SA Vb 0) 8 (ELit PML.VT_VISITOR)) && PB.has cells (KUnk (SA SEG 0) WLEN)
        && PB.prove cells (KRange (APC.esub s1 SEG) 0 16384) && PB.prove cells (KRange (APC.esub WEND s1) 1 16384)
        && PB.prove cells (KRange (APC.esub BX (APC.eadd (PB2.pv_size pv) (APC.esub WEND s1))) 0 67108864)
        && ((expr_eqb a1e pe && expr_eqb a2e (PB2.pv_size pv))
            || (PB.prove cells (KRange (APC.esub a1e SEG) 0 16384) && PB.prove cells (KRange (APC.esub WEND (APC.eadd a1e a2e)) 0 16384) && PB.prove cells (KRange a2e 0 16384))))%bool
   | None => false
   end)%bool.

Definition leaf_chk (i : nat) (c : CC.cutpoint) (k : nat) (ps : SR.post_spec) (t : CC.tag) : bool :=
  match t with
  | CC.TGoto j _ => (kind_eqb (kind_of i) KPre && kind_eqb (kind_of j) KPre && foot_pre_chk c)%bool
  | CC.TOther pc =>
      if Z.eqb pc RETPC then
        match kind_of i with KPre => exit_pre_chk i c ps | KSetEc => exit_setec_chk i c ps | KEsv => exit_esv_chk i c ps end
      else
        (kind_eqb (kind_of i) KPre && foot_pre_chk c && Z.eqb (SR.ps_pc ps) pc &&
         match CH2.ret_of G.RETS i k with
         | Some j => match nth_error G.CPS j with
                     | Some cj =>
                         if Z.eqb pc PUSHB then (kind_eqb (kind_of j) KPre && isSome (PB.pushb_chk GT.NF G.HDECL Pb 224 132 c ps cj (nth i G.BLS []) (nth j G.BLS [])))%bool
                         else if Z.eqb pc APPEND then (kind_eqb (kind_of j) KPre && isSome (PB.appendb_chk GT.NF G.HDECL Pb 224 SEG WLEN 132 c ps cj (nth i G.BLS []) (nth j G.BLS [])))%bool
                         else if Z.eqb pc SETEC then (kind_eqb (kind_of j) KSetEc && match PB2.setec_chk GT.NF G.HDECL Eb 0 c ps cj (nth i G.BLS []) (nth j G.BLS []) with Some ci => Nat.leb GT.NF (CH2.ci_nx ci) | None => false end)%bool      (* [comment removed for export] *)
                         else if Z.eqb pc ESV then (kind_eqb (kind_of j) KEsv && isSome (PBX.ptrans_chkx GT.NF G.HDECL Eb 0 Pb 0 11136 Vb PML.LIT_LO 14 c ps cj (nth i G.BLS []) (nth j G.BLS []))
                                                    && esv_leaf_chk i c ps cj)%bool
                         else false
                     | None => false end
         | None => false end)%bool
  end.
End PSC.

Lemma heap_ok3 : CH2.heap_chk3 PSC.GT.NF PSC.G.HDECL PSC.G.BLS PSC.G.CPS PSC.G.TAGS = true.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00vv!2,@+:,;!3+=+:!5'_F'^V'_G'^\'_H'_I,;").
Qed.
Lemma leaf_ok : CH2.leaves_all PSC.G.CPS PSC.G.TAGS PSC.leaf_chk = true.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00vv!2,@+:,;!3+=+:!3'_J'_H'_I'_K,;").
Qed.
